use std::cell::RefCell;
use std::path::Path;
use std::path::PathBuf;

use logger::StdioLogger;
use logger_srcfile::WrapFileLogger;
use oxc_allocator::Allocator;

use ast_segmenter::segment_info::Segment;

thread_local! {
    static PARSE_ARENA: RefCell<Allocator> = RefCell::new(Allocator::default());
}

#[derive(Debug, thiserror::Error)]
pub enum SourceFileParseError {
    #[error("Auto-generated file")]
    AutogeneratedFile,
    #[error("Unable to load {0} file: {1}")]
    LoadFile(PathBuf, std::io::Error),
    #[error("TypeScript syntax error in {0}: {1}")]
    TypeScriptSyntax(PathBuf, String),
    #[error("Parser error in {0}: {1}")]
    Parser(PathBuf, String),
}

/// Parses a source file and returns per-statement segments via `ast_segmenter::segment_file`.
///
/// Uses a per-worker thread-local arena so Rayon callers reuse the same backing
/// allocation across files on each worker thread. The arena is reset at the end
/// of each call so visitor outputs (`Vec<Segment>`) must be fully owned.
pub fn get_file_segments(file_path: &Path) -> Result<Vec<Segment>, SourceFileParseError> {
    let source = std::fs::read_to_string(file_path)
        .map_err(|e| SourceFileParseError::LoadFile(file_path.to_path_buf(), e))?;
    if source.contains("// This file is auto-generated") {
        return Err(SourceFileParseError::AutogeneratedFile);
    }

    PARSE_ARENA.with(|arena_cell| {
        let arena = arena_cell.borrow();
        let ret = oxc_utils_parse::parse_file(&arena, &source, file_path);
        if !ret.errors.is_empty() {
            let msg = ret
                .errors
                .iter()
                .map(|e| e.message.to_string())
                .collect::<Vec<_>>()
                .join("\n");
            drop(arena);
            arena_cell.borrow_mut().reset();
            return Err(SourceFileParseError::Parser(file_path.to_path_buf(), msg));
        }
        if ret.panicked {
            drop(arena);
            arena_cell.borrow_mut().reset();
            return Err(SourceFileParseError::TypeScriptSyntax(
                file_path.to_path_buf(),
                "parser panicked".into(),
            ));
        }

        let semantic = oxc_semantic::SemanticBuilder::new().build(&ret.program).semantic;

        let stdio_logger = StdioLogger::new();
        let file_logger = WrapFileLogger::new(
            file_path.display().to_string(),
            source.clone(),
            &stdio_logger,
        );

        let segments = ast_segmenter::segment_file(&file_logger, &ret.program, &semantic);

        // All owned data is extracted; drop the borrow and reset the arena for next call.
        drop(semantic);
        drop(ret);
        drop(arena);
        arena_cell.borrow_mut().reset();

        Ok(segments)
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tracker_preserves_generated_file_skip_policy() {
        let dir = test_tmpdir::test_tmpdir!(
            "generated.ts" => "// This file is auto-generated\nexport const value = 1;"
        );
        assert!(matches!(
            get_file_segments(&dir.root_join("generated.ts")),
            Err(SourceFileParseError::AutogeneratedFile)
        ));
    }

    #[test]
    fn thread_local_arena_is_reused_across_calls() {
        // Write two small TS files into a temp directory.
        let dir = test_tmpdir::TmpDir::new_with_content(&test_tmpdir::map! {
            "a.ts" => "export const a = 1;",
            "b.ts" => "export const b = 2;"
        });
        let file_a = dir.root_join("a.ts");
        let file_b = dir.root_join("b.ts");

        // Parse the first file to prime the arena.
        let result_a = get_file_segments(&file_a);
        assert!(result_a.is_ok(), "first parse failed: {:?}", result_a);

        // Record the arena's capacity after reset — should be > 0 because
        // reset keeps the largest chunk.
        let cap_after_first = PARSE_ARENA.with(|cell| cell.borrow().capacity());

        // Parse the second (equally small) file.
        let result_b = get_file_segments(&file_b);
        assert!(result_b.is_ok(), "second parse failed: {:?}", result_b);

        let cap_after_second = PARSE_ARENA.with(|cell| cell.borrow().capacity());

        // The arena capacity should not have grown — the backing allocation
        // from the first call is reused.
        assert_eq!(
            cap_after_first, cap_after_second,
            "arena capacity grew between calls ({} → {}); thread-local reuse is broken",
            cap_after_first, cap_after_second,
        );
    }
}
